# Simulator Generator Laporan Kualitas Data Docs Sederhana (HTML / Markdown Renderer)
class DataDocsReportGenerator:
    @staticmethod
    def generate_summary(suite_name, total_evaluated, validation_results):
        passed = sum(1 for r in validation_results if r['success'])
        total_assertions = len(validation_results)
        success_rate = (passed / total_assertions) * 100 if total_assertions > 0 else 0

        report_lines = [
            f"=== GREAT EXPECTATIONS DATA DOCS: {suite_name.upper()} ===",
            f"Total Baris Dievaluasi : {total_evaluated:,} baris",
            f"Tingkat Keberhasilan  : {success_rate:.1f}% ({passed}/{total_assertions} Asersi Sukses)",
            "Detail Hasil Validasi Asersi:"
        ]
        for idx, res in enumerate(validation_results, 1):
            icon = '[PASS]' if res['success'] else '[FAIL]'
            report_lines.append(f"  {idx}. {icon} {res['rule']:<35} | Pelanggaran: {res['unexpected_count']} baris")
        return "\n".join(report_lines)

mock_results = [
    {'rule': 'expect_column_values_to_not_be_null(user_id)', 'success': True, 'unexpected_count': 0},
    {'rule': 'expect_column_values_to_be_between(age, 18, 90)', 'success': True, 'unexpected_count': 0},
    {'rule': 'expect_column_values_to_be_unique(national_id)', 'success': False, 'unexpected_count': 14}
]

html_summary = DataDocsReportGenerator.generate_summary('customer_gold_mart', 50000, mock_results)
print(html_summary)
print('Kesimpulan: Data Docs menyajikan bukti visual kelaikan data yang ramah bagi seluruh tim.')

# Simulator Integrasi Airflow DAG dengan Great Expectations Operator Quality Gate
class AirflowGXPipelineSimulation:
    def __init__(self):
        self.pipeline_state = 'INITIALIZED'

    def task_1_ingest_raw_s3(self):
        return {'status': 'SUCCESS', 'records_loaded': 100000}

    def task_2_gx_quality_gate(self, is_valid_quality=True):
        if not is_valid_quality:
            self.pipeline_state = 'HALTED_BY_GX_OPERATOR'
            raise RuntimeError('AirflowFailException: GX Checkpoint failed! Menahan pemrosesan hilir.')
        return {'status': 'PASSED', 'data_docs_link': 's3://docs/run_latest.html'}

    def task_3_dbt_transform_silver(self):
        return {'status': 'SUCCESS', 'models_built': 12}

    def task_4_trigger_ai_model_training(self):
        return {'status': 'SUCCESS', 'model_version': 'xgboost_v3'}

pipeline = AirflowGXPipelineSimulation()
t1 = pipeline.task_1_ingest_raw_s3()
t2 = pipeline.task_2_gx_quality_gate(is_valid_quality=True) # Lolos gerbang kualitas
t3 = pipeline.task_3_dbt_transform_silver()
t4 = pipeline.task_4_trigger_ai_model_training()

print('Simulasi Pipeline Terpadu Airflow + GX + dbt:')
print(f"  Tahap 1 (Ingesti S3)   : {t1['status']} ({t1['records_loaded']} baris)")
print(f"  Tahap 2 (GX Gatekeeper): {t2['status']} -> Data Docs: {t2['data_docs_link']}")
print(f"  Tahap 3 (dbt Transform): {t3['status']} ({t3['models_built']} model selesai)")
print(f"  Tahap 4 (ML Training)  : {t4['status']} (Model {t4['model_version']} siap deploy)")
print('Kesimpulan: Great Expectations Operator bertindak sebagai gerbang pengaman otomatis di Airflow.')
